#include <stdio.h>
int gcd(int a, int b) {
  while (b != 0) {
    int t = b;
    b = a % b;
    a = t;
  }
  return a;
}
int main() {
  int a = 48, b = 18;
  printf("%d", gcd(a, b));
}

#include <stdio.h>

int gcd(int a, int b) {
  if (b == 0) return a;
  return gcd(b, a % b);
}

int main() {
  int x = 252, y = 105;
  printf("%d", gcd(x, y));
  return 0;
}

