#include <stdio.h>
struct Node { struct Node* next; int val; };
int main() {
    struct Node n1={0,3}, n2={0,6}, n3={0,9}, n4={0,12};
    n1.next=&n2; n2.next=&n3; n3.next=&n4;
    struct Node* cur = &n1;
    int product = 1;
    int idx = 0;
    while (cur) {
        if (idx % 2 == 0) product *= cur->val;
        cur = cur->next;
        idx++;
    }
    printf("%d\n", product);
    return 0;
}

#include <stdio.h>
int main() {
    int cnt = 0;
    for(int n=2; n<=30; n++) {
        int isPrime = 1;
        for(int j=2; j*j<=n; j++) {
            if(n % j == 0) { isPrime = 0; break; }
        }
        if(isPrime) cnt++;
    }
    printf("%d", cnt);
    return 0;
}

